INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dd0c4fbd-0bb2-58ae-b288-7b9070fb95e1', 'ceb07a4e-1997-52ef-b120-b35b0957a8d5', '5e4dd646-af17-5cc8-9d1e-f40d8748a1a3', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Id', 'Immutable Supplier role identity. Connects procurement purchase orders receipts invoices payments returns credits claims resolutions and supplier performance. Supplier identifies the role while PartyRole and Party identify the underlying party. Preserves supplier traceability across procure-to-pay reverse procurement claim recovery and performance management. Required for stable supplier history. Must be unique: a save is rejected if another Supplier already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('81b77ecb-5249-5f03-8629-e263074250ac', 'ceb07a4e-1997-52ef-b120-b35b0957a8d5', 'ce2a294f-2bb5-5f6d-8b06-6b6e01943aa9', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Party Role', 'PartyRole backing the Supplier specialization. Navigates to common party identity and role information. Supplier must not duplicate Party identity. Supplies shared party context to procurement and financial workflows. Required for role specialization. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Supplier already uses this value.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c667f76e-2891-562e-8218-21776458c493', 'ceb07a4e-1997-52ef-b120-b35b0957a8d5', '82179d0f-6be5-544f-92c6-27ce13fc2e43', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Supplier Code', 'Enterprise supplier business reference. Used on purchase orders receipts invoices returns credits payments claims portals reports and integrations. Distinct from legal name and external registration identifiers. Identifies the supplier across procurement settlement recovery and performance. Required for operational recognition. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Supplier already uses this value. Up to 100 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
