VALUES ('05ae6ada-8fbf-558d-856d-04d402ec30d1', '32c875c3-8ff0-5a7a-b1b6-6ab698cfc3b0', 'total_amount', 'Total Amount', 'Total offered commercial amount. Summarizes the supplier offer for comparison. Sourcing analysis, approvals, and order conversion. Must reconcile with detailed offer basis when line detail is modeled. Optional while offer pricing is incomplete.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
