INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8d2be21c-aa77-5796-afa9-7fdf776d7ae5', '709d6477-9454-5630-a15d-1bb1fde247fa', 'status', 'Status', 'Controlled receiving-document lifecycle state. Indicates whether receipt evidence can affect fulfillment and inventory. Controls receiving progression and authorized corrections. SupplierReturn is a later reverse-procurement event and does not rewrite receipt status. Controls receiving progression and authorized corrections. The status of the goods receipt is draft; set it when that is what the business means for this record. The status of the goods receipt is received; set it when that is what the business means for this record. The status of the goods receipt is inspection pending; set it when that is what the business means for this record. The status of the goods receipt is accepted; set it when that is what the business means for this record. The status of the goods receipt is partially accepted; set it when that is what the business means for this record. The status of the goods receipt is rejected; set it when that is what the business means for this record. The status of the goods receipt is cancelled; set it when that is what the business means for this record.', 1005, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('54ae18c4-c09a-5826-8ffa-2180c3c0c967', '709d6477-9454-5630-a15d-1bb1fde247fa', 'received_quantity', 'Received Quantity', 'Total quantity physically recorded as received. Sum of line received quantities. Receiving and audit. SupplierReturn eligibility is derived from accepted receipt evidence, not received quantity alone. Provides original physical receipt basis. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
