INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('270cfba3-5428-54ca-b999-016f610abb0e', '3e81d672-49b4-5e67-be4c-e6271df5b2b5', '8d2be21c-aa77-5796-afa9-7fdf776d7ae5', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Status', 'Controlled receiving-document lifecycle state. Indicates whether receipt evidence can affect fulfillment and inventory. Controls receiving progression and authorized corrections. SupplierReturn is a later reverse-procurement event and does not rewrite receipt status. Controls receiving progression and authorized corrections. The status of the goods receipt is draft; set it when that is what the business means for this record. The status of the goods receipt is received; set it when that is what the business means for this record. The status of the goods receipt is inspection pending; set it when that is what the business means for this record. The status of the goods receipt is accepted; set it when that is what the business means for this record. The status of the goods receipt is partially accepted; set it when that is what the business means for this record. The status of the goods receipt is rejected; set it when that is what the business means for this record. The status of the goods receipt is cancelled; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('57146dc2-b061-5238-8cb5-d0b20f7e6326', '3e81d672-49b4-5e67-be4c-e6271df5b2b5', '54ae18c4-c09a-5826-8ffa-2180c3c0c967', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Received Quantity', 'Total quantity physically recorded as received. Sum of line received quantities. Receiving and audit. SupplierReturn eligibility is derived from accepted receipt evidence, not received quantity alone. Provides original physical receipt basis. Required. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
