INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b752bbc6-14ed-5354-b77f-6a825d5ab398', '3e81d672-49b4-5e67-be4c-e6271df5b2b5', '017de4bb-8903-5581-8156-24b405549fa7', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Accepted Quantity', 'Quantity accepted after receiving controls. Sum of line accepted quantities that may become inventory. Inventory posting, PO fulfillment and invoice matching. SupplierReturnLine eligibility is normally based on accepted quantity and subsequent prior returns. Provides authoritative accepted receipt basis for later supplier returns. Required. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
