INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('64210344-66f2-5863-85bc-1f9e2b278f4c', '3e81d672-49b4-5e67-be4c-e6271df5b2b5', '7435da94-b2db-5314-a07d-5042776384ae', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Notes', 'Receiving notes and operational context. Human-readable context for receipt exceptions or inspection. Operations and audit. Does not replace structured disposition or return evidence. Supports review. Optional. Up to 2000 characters.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
