VALUES ('0453f112-32d9-57e0-818f-798608bc5453', '3e81d672-49b4-5e67-be4c-e6271df5b2b5', 'daca4e30-039f-5b09-b33e-33d3625b0880', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Supplier', 'Supplier that delivered the receipt. Identifies the commercial party responsible for the delivery. Receiving, procurement, audit and supplier return processing. Supplies supplier context for subsequent returns. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
