INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d6fc51a-44a7-5193-bdc3-0af82fc2639a', '577e438a-ee71-5a07-8238-2fc65b87a83d', '3966f6bb-e0a8-5b1d-addf-be6a12ab64bb', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Id', 'Stable identity of the supplier claim. Identifies one claim independently of its supplier source transaction return inspection resolution or financial settlement. Used for supplier performance dispute management quality warranty recovery and audit. SupplierClaim is a case/evidence record; SupplierReturn handles physical reversal and SupplierCreditNote or SupplierDebitNote handles explicit financial adjustment. Root reference through claim investigation resolution and closure. Required. Must be unique: a save is rejected if another Supplier Claim already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7333f98c-dc80-574a-af89-0e8ab88f6437', '577e438a-ee71-5a07-8238-2fc65b87a83d', 'ed8f99ea-97a2-500f-9d1b-56d4ab3deba9', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Claim Number', 'Business-facing supplier claim reference. Identifies the claim for procurement quality and supplier communication. Used in correspondence investigations reporting and reconciliation. Distinct from PurchaseOrder GoodsReceipt Invoice SupplierReturn and financial adjustment numbers. Provides the operational reference throughout the claim lifecycle. Required. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Supplier Claim already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3b737746-0b5f-5541-aee5-b37e4c9d39cf', '577e438a-ee71-5a07-8238-2fc65b87a83d', '61199b22-8843-54cd-b686-fd21ca0776a5', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Claim Date', 'Date and time the claim was raised. Establishes when the organization formally asserted the supplier issue. Supports SLA measurement dispute aging supplier performance and audit. Distinct from receipt inspection return resolution and financial-document dates. Anchors claim chronology. Required. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
