INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('26b2bb1e-6e8a-5520-a646-258801ea2860', '577e438a-ee71-5a07-8238-2fc65b87a83d', '14632bc8-f731-5b86-aac4-c79f404e3420', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Status', 'Lifecycle state of the supplier claim. Indicates whether the issue is being prepared investigated accepted disputed resolved or closed. Controls investigation supplier response settlement and escalation. Claim status is independent from SupplierReturn SupplierCreditNote SupplierDebitNote and SupplierClaimResolution statuses. Coordinates the case while physical and financial effects remain separate transactions. Required. The status of the supplier claim is draft; set it when that is what the business means for this record. The status of the supplier claim is open; set it when that is what the business means for this record. The status of the supplier claim is under review; set it when that is what the business means for this record. The status of the supplier claim is accepted; set it when that is what the business means for this record. The status of the supplier claim is partially accepted; set it when that is what the business means for this record. The status of the supplier claim is rejected; set it when that is what the business means for this record. The status of the supplier claim is resolved; set it when that is what the business means for this record. The status of the supplier claim is closed; set it when that is what the business means for this record. The status of the supplier claim is cancelled; set it when that is what the business means for this record. The status of the supplier claim is escalated; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c4788734-1d7f-5eac-ae9a-2ad8bd9ab37a', '577e438a-ee71-5a07-8238-2fc65b87a83d', '5d07c926-49b2-52bf-80ae-6046136cf190', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Claim Type', 'Classification of the supplier issue. States the principal business nature of the claim. Drives routing evidence requirements supplier scorecards and analytics. May be supported by QualityInspection or receiving evidence and may result in a return credit debit or other resolution. Determines investigation and resolution policy. Required. The claim type of the supplier claim is quality; set it when that is what the business means for this record. The claim type of the supplier claim is damage; set it when that is what the business means for this record. The claim type of the supplier claim is shortage; set it when that is what the business means for this record. The claim type of the supplier claim is overage; set it when that is what the business means for this record. The claim type of the supplier claim is wrong item; set it when that is what the business means for this record. The claim type of the supplier claim is warranty; set it when that is what the business means for this record. The claim type of the supplier claim is service; set it when that is what the business means for this record. The claim type of the supplier claim is commercial; set it when that is what the business means for this record. The claim type of the supplier claim is delivery; set it when that is what the business means for this record. The claim type of the supplier claim is documentation; set it when that is what the business means for this record. The claim type of the supplier claim is other; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('75d61929-fd56-58c1-9835-e8270b03f9da', '577e438a-ee71-5a07-8238-2fc65b87a83d', '437d6013-66ef-522a-a649-cc6e3c1eda72', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Claimed Amount', 'Financial value asserted by the organization in the claim. Represents requested or estimated monetary recovery before supplier agreement or final adjustment. Supports negotiation exposure reporting and recovery analysis. It is not an accounting posting and must not be confused with SupplierCreditNote.totalAmount or SupplierDebitNote.totalAmount. Provides commercial context for settlement negotiation. Optional for non-financial claims.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('73f45171-6723-5a10-8bef-a9cb8c997cbf', '577e438a-ee71-5a07-8238-2fc65b87a83d', '03af7b1b-89b8-5f91-b6c5-2ca0e3db296b', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Resolution Code', 'Agreed outcome category of the supplier claim. Records the high-level outcome without itself executing the resulting transaction. Supports supplier performance recovery analytics and downstream workflow routing. Detailed authorization is represented by SupplierClaimResolution; RETURN may create SupplierReturn; CREDIT may create SupplierCreditNote; DEBIT_ADJUSTMENT may create SupplierDebitNote. Summarizes the resolution after agreement. Optional until resolution is agreed. The resolution code of the supplier claim is no action; set it when that is what the business means for this record. The resolution code of the supplier claim is replacement; set it when that is what the business means for this record. The resolution code of the supplier claim is repair; set it when that is what the business means for this record. The resolution code of the supplier claim is return; set it when that is what the business means for this record. The resolution code of the supplier claim is credit; set it when that is what the business means for this record. The resolution code of the supplier claim is debit adjustment; set it when that is what the business means for this record. The resolution code of the supplier claim is price adjustment; set it when that is what the business means for this record. The resolution code of the supplier claim is accepted exception; set it when that is what the business means for this record. The resolution code of the supplier claim is rejected; set it when that is what the business means for this record.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
