-- --------------------------------------------------------------------------
-- Supplier Claim Resolution (bus_supplier_claim_resolution)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('284e6766-d57f-5ffd-a597-072b0292977d', 'Supplier Claim Resolution', 'Maintain Supplier Claim Resolution records', 'Create, find and maintain Supplier Claim Resolution records. The list shows every Supplier Claim Resolution you have access to — select a row to open it, or use New to add one. Each row is a single Supplier Claim Resolution, described by 9 fields.

Id and Resolution Number are unique: no two Supplier Claim Resolution records may share the same value, and a save that would duplicate one is rejected. Resolution Number, Resolution Date, Resolution Type, Status and Supplier Claim must be filled in before the record can be saved.

Every Supplier Claim Resolution points at Supplier, Supplier Claim and Supplier Performance Assessment. Choose the linked record from the lookup on those fields rather than typing an identifier. Supplier Credit Note, Supplier Debit Note, Supplier Debit Note Line and Supplier Return refer back to Supplier Claim Resolution, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Supplier Claim Resolution then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Supplier Claim Resolution with no rules or workflows attached is marked Final immediately.', 'factory', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('899f372a-43c5-56f2-9ae0-563f52b3a33b', 'bus_supplier_claim_resolution', 'Supplier Claim Resolution', 'Converts a supplier claim decision into a controlled auditable execution plan without conflating the case remedy and resulting transactions. SupplierClaim explains the problem; SupplierClaimResolution records the agreed remedy; SupplierReturn SupplierCreditNote SupplierDebitNote and Payment execute distinct physical or financial consequences. Supplier dispute management procurement recovery accounts payable quality logistics and audit. The resolution bridges case management and execution while preserving independent transaction histories. SupplierClaim accepted → remedy negotiated → SupplierClaimResolution approved → required return/credit/debit/payment executed → evidence reconciled → claim resolved/closed. Draft → approved → in execution → partially executed/executed, with failed and cancelled paths. Changes to the originating claim or downstream execution evidence require resolution revalidation; completed downstream transactions are corrected through their own compensating workflows. A quality claim is accepted for three defective units and EUR 300 recovery. The resolution authorizes RETURN plus CREDIT, links the resulting SupplierReturn and SupplierCreditNote, and becomes executed only after both required outcomes reconcile.', 'factory', 'A', FALSE, FALSE, FALSE, TRUE, '284e6766-d57f-5ffd-a597-072b0292977d', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('43f835cd-e348-53fd-8bc2-09b77989b713', '284e6766-d57f-5ffd-a597-072b0292977d', '899f372a-43c5-56f2-9ae0-563f52b3a33b', 'Supplier Claim Resolution', 'Shows one Supplier Claim Resolution at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Supplier, Supplier Claim and Supplier Performance Assessment are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('91097eee-b35b-5e31-ba2d-33ff6d63412a', '899f372a-43c5-56f2-9ae0-563f52b3a33b', 'id', 'Id', 'Stable identity of the claim resolution. Identifies one authorized resolution decision independently of the originating claim and downstream transactions. Used for approvals reconciliation audit and supplier performance. SupplierClaim records the case; this record captures the agreed outcome; SupplierReturn SupplierCreditNote SupplierDebitNote and Payment provide execution evidence. Stable reference across approval execution and closure. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4a3a4924-3a9f-5d6a-b036-77fbaaaa65ce', '899f372a-43c5-56f2-9ae0-563f52b3a33b', 'resolution_number', 'Resolution Number', 'Human-facing resolution reference. Identifies the resolution decision for operational and supplier communication. Used in approvals correspondence reconciliation and audit. Distinct from the SupplierClaim claimNumber and downstream transaction numbers. Correlates resolution activity. Required.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
