INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7a37b6c4-f75d-5837-9fd7-c6ff059fbfa1', '8031adea-5a3c-5c3f-92c9-71cade0fc2ec', 'status', 'Status', 'Lifecycle state of the supplier credit application. Indicates whether the application currently reduces payable exposure. Controls SupplierCreditNote and Invoice projections. SupplierCreditNote and Invoice statuses remain independent historical facts. ACTIVE creates the application effect; reversal removes it through a compensating event. Required. The status of the supplier credit note application is draft; set it when that is what the business means for this record. The status of the supplier credit note application is active; set it when that is what the business means for this record. The status of the supplier credit note application is reversed; set it when that is what the business means for this record. The status of the supplier credit note application is cancelled; set it when that is what the business means for this record.', 1032, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
