VALUES ('dc9507a7-9e0f-5917-85b8-012d51c7f45f', '9d955f8d-a8cc-5914-8286-7ebda9cecf92', 'amount_remaining', 'Amount Remaining', 'Unapplied portion of the posted supplier debit. Represents debit value still available for payable application or governed settlement handling. Reconciliation supplier statements and resolution tracking. Determines whether the debit is fully applied. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
