VALUES ('c118d48e-0631-55d0-9f60-fd461401a593', 'b1efcc98-e7fd-5c0b-ae17-652dbea30f10', '3c79b738-1d70-51e6-833c-ba7fcdea66f4', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Status', 'Lifecycle state of the debit application. Separates preparation from effective application and later reversal. Controls payable projections and remaining debit balance. Application status does not replace SupplierDebitNote or Invoice status. ACTIVE contributes to settlement projections; REVERSED removes its active effect through compensating evidence. Required. The status of the supplier debit note application is draft; set it when that is what the business means for this record. The status of the supplier debit note application is active; set it when that is what the business means for this record. The status of the supplier debit note application is reversed; set it when that is what the business means for this record. The status of the supplier debit note application is cancelled; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bca73b71-f73f-540b-b255-4a2502ec4a77', 'b1efcc98-e7fd-5c0b-ae17-652dbea30f10', 'a0b1b798-e462-5410-ab2f-270d8e09b9b5', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Reversal Of Application', 'Prior application being reversed. Provides explicit lineage for a corrective reversal. Audit, reconciliation and error correction. Reversal is a new event and does not mutate the original application. Links compensating evidence to the prior application. Required when status is REVERSED under the reversal model.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('abf2a285-b176-5dd5-97ce-5fa623001dd4', 'b1efcc98-e7fd-5c0b-ae17-652dbea30f10', '86ad3f4d-af95-596d-8224-9b5bbf29e142', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Supplier Debit Note', 'Posted supplier debit being applied. Identifies the source financial adjustment. Remaining-balance and audit reconciliation. Supplies available debit amount and supplier context. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
