VALUES ('4dcba74b-b5e1-55c5-8a41-c5f2146e1964', '41946a1b-a172-5315-ae41-4e028235eaa1', '07be30d6-caa2-53f8-a69d-89b50fcaea6c', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Status', 'Lifecycle state of the supplier performance assessment. Separates calculation, review, approval, publication and replacement of scorecard results. Controls whether the assessment may be changed or consumed by supplier governance. Does not change the status of Supplier, PurchaseOrder, GoodsReceipt, Invoice or SupplierClaim records. PUBLISHED makes the assessment an approved historical scorecard; corrections use a replacement or superseding assessment. Required. The status of the supplier performance assessment is draft; set it when that is what the business means for this record. The status of the supplier performance assessment is in review; set it when that is what the business means for this record. The status of the supplier performance assessment is approved; set it when that is what the business means for this record. The status of the supplier performance assessment is published; set it when that is what the business means for this record. The status of the supplier performance assessment is superseded; set it when that is what the business means for this record. The status of the supplier performance assessment is cancelled; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5ec63e98-0a6c-53ee-9aaa-4bbf62e975df', '41946a1b-a172-5315-ae41-4e028235eaa1', 'c4edf256-ecc1-558f-9c7d-925af80274de', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Overall Score', 'Aggregate supplier performance score for the assessment scope. Represents the governed result of the configured supplier scorecard calculation. Supplier ranking, sourcing decisions, escalation and trend analysis. Must be derived from defined performance measures and must not be treated as raw transaction evidence. Supports approval and supplier governance decisions. Optional until score calculation is complete.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dd38ea10-0806-52dd-8d61-7ce7af50480b', '41946a1b-a172-5315-ae41-4e028235eaa1', '4e67edba-49c8-5341-b656-7269e57d084a', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Rating', 'Interpreted supplier performance rating. Converts the approved score or governed assessment criteria into a business-facing performance category. Supplier segmentation, review cadence and improvement decisions. Rating is an assessment conclusion, not a replacement for underlying delivery, quality, claim or commercial evidence. Supports governance actions and escalation. Optional until the assessment is evaluated. The rating of the supplier performance assessment is excellent; set it when that is what the business means for this record. The rating of the supplier performance assessment is good; set it when that is what the business means for this record. The rating of the supplier performance assessment is acceptable; set it when that is what the business means for this record. The rating of the supplier performance assessment is needs improvement; set it when that is what the business means for this record. The rating of the supplier performance assessment is unsatisfactory; set it when that is what the business means for this record.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('859acb02-fab6-54d1-9006-8dfcd41c3c15', '41946a1b-a172-5315-ae41-4e028235eaa1', '1e7beb5f-09c8-5f98-af16-945d8df71358', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Notes', 'Qualitative context supporting the assessment. Records material observations, explanations or agreed context that structured scores do not capture. Supplier review, audit and improvement planning. Supplements but does not replace measurable evidence. Optional. Up to 4000 characters.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ece737e7-2c57-58ce-8615-cc4b50830b44', '41946a1b-a172-5315-ae41-4e028235eaa1', '4df94956-f7e7-505a-8481-5c28b9237805', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Supplier', 'Supplier being evaluated. Identifies the external party whose performance is assessed. Supplier governance, sourcing and improvement management. Supplies the master relationship and qualification context. Required — the record cannot be saved while this is empty.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
