VALUES ('83849584-2237-5165-a1d4-7510cd6e4b42', 'bus_currency_status', 'Currency Status', 'The values of currency status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '5726914c-27fe-51d8-8cfb-3acf2afde858', 'U', TRUE, 'system', 'system', NOW(), NOW())
