INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('35c6c23a-1e45-589c-b7a8-e9c97402b91a', 'Supplier Claim Resolution Status', 'Maintain Supplier Claim Resolution Status records', 'Create, find and maintain Supplier Claim Resolution Status records. The list shows every Supplier Claim Resolution Status you have access to — select a row to open it, or use New to add one. Each row is a single Supplier Claim Resolution Status, described by 6 fields.

Id and Code are unique: no two Supplier Claim Resolution Status records may share the same value, and a save that would duplicate one is rejected. Code, Name, Sequence and Is Active must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Supplier Claim Resolution Status then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Supplier Claim Resolution Status with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('10af0c59-3dd7-50bd-a587-daf233975f7b', 'bus_supplier_claim_resolution_status', 'Supplier Claim Resolution Status', 'The values of supplier claim resolution status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '35c6c23a-1e45-589c-b7a8-e9c97402b91a', 'U', TRUE, 'system', 'system', NOW(), NOW())
