INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c6e9e745-ed8a-5ab0-b318-ffb0636a29b0', '8e6ec59d-2cb6-5443-8535-aa8bb08835d2', '99fcf47c-cdbd-59ce-a4cf-6eb999e133d2', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Quantity', 'The quantity of goods, materials, assets, or service units requested by the requester. Used for approval, sourcing, supplier quotation, planning, and eventual conversion into a purchase commitment. Quantity requires Product and UnitOfMeasure context to be meaningful and may differ from the quantity eventually ordered. Required because procurement demand must state the requested magnitude. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ec83e9f7-3ddd-5910-ae7e-030516eff409', '8e6ec59d-2cb6-5443-8535-aa8bb08835d2', '871da4be-aaac-5087-b1a1-ea5e96b757ed', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Requested Date', 'The date by which the requester needs the requested goods or service to be available or completed. Used for prioritization, sourcing, purchasing lead-time analysis, supplier selection, and delivery planning. This is an internal need date and is distinct from the PurchaseOrder requestedDeliveryDate, Supplier promise date, and actual receipt date. Optional when the requester has no fixed need-by date.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('17eb1af2-cfcd-5d94-9fa5-e917adf64bd0', '8e6ec59d-2cb6-5443-8535-aa8bb08835d2', '09d06a89-58c3-52a8-8616-ecac0c2e59e2', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Description', 'The human-readable description of the requested item or service, including requirements that may not be represented by the Product reference alone. Used by approvers and buyers to understand the demand, obtain quotations, clarify specifications, and communicate requirements to suppliers. Description supplements Product; it must not silently replace a known Product identity when standardized master data exists. Required because procurement demand must remain understandable even when product master data is incomplete. Required — the record cannot be saved while this is empty. Up to 1000 characters.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2932b5d4-b741-5ef4-8644-9b7ccf961b93', '8e6ec59d-2cb6-5443-8535-aa8bb08835d2', '4841407a-0093-513e-a4ba-3da0ec0ce216', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Requisition', 'Identifies the PurchaseRequisition that owns this internal procurement demand. Supplies requester, organization, approval, supplier preference, and requisition lifecycle context. Every requisition line belongs to exactly one PurchaseRequisition. The parent requisition controls the internal authorization context; the line provides the measurable demand. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8587ab9d-6b3e-59db-80fc-4ae4983b535d', '8e6ec59d-2cb6-5443-8535-aa8bb08835d2', '87ddf450-aa72-506c-b410-d665ced554b9', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Product', 'Identifies the standardized Product being requested when the demand can be expressed using product master data. Enables sourcing, catalog selection, inventory checks, specification validation, and conversion to a PurchaseOrderLine. Zero or one Product may be referenced because some requisitions begin as free-text or service requirements. A missing Product does not invalidate the demand; it indicates that purchasing may need to identify or create the appropriate product definition.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('68797c0c-603a-577d-87bd-264bee351140', '8e6ec59d-2cb6-5443-8535-aa8bb08835d2', 'e8e4d00d-ff57-5da6-a2e7-77492f434941', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Unit Of Measure', 'Defines the unit in which the requested quantity is expressed. Used to interpret quantities during approval, sourcing, quotation comparison, ordering, receipt, and conversion. Zero or one unit may be specified; the product''s default unit may be inherited where applicable. UnitOfMeasure gives semantic meaning to quantity and supports conversion when the ordered unit differs from the requested unit.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
