VALUES ('72ae11a3-6b5d-5ac4-b0be-9e19e56c6ad0', '2b34b6e8-3622-576f-a6a7-c6612e4115c1', 'df83bfa3-7875-532d-82c8-0f922e55aadc', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Line Number', 'Sequence number within the receipt. Identifies the receiving line. Documents and audit. Distinct from PurchaseOrderLine and SupplierReturnLine numbering. Supports deterministic receipt reconstruction. Required. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
