-- --------------------------------------------------------------------------
-- Supplier Credit Note Line (bus_supplier_credit_note_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6e0315ad-8603-5350-adb9-15fc133b9829', 'bus_supplier_credit_note_line', 'Supplier Credit Note Line', 'Provides the auditable quantity, value, discount and tax detail behind a supplier payable adjustment. It is the financial mirror of an original supplier invoice line for the credited portion, not a replacement of that line. Accounts payable, tax, supplier reconciliation, audit and accounting. SupplierReturnLine explains the physical cause; InvoiceLine explains the original financial claim; SupplierCreditNoteLine explains the approved financial reduction. Identify eligible invoice evidence → determine credited quantity/value → apply original pricing and tax evidence → calculate credit → approve → post to SupplierCreditNote. Three units originally invoiced at EUR 100 are returned. The line preserves quantity 3 and original price EUR 100, applies the applicable historical discount/tax treatment, and contributes the resulting amount to the supplier credit note.', 'factory', 'A', FALSE, FALSE, FALSE, TRUE, 'adf2a531-9330-5b8a-84c1-cae0839fedae', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5f5586f0-9a8b-5ee1-85d9-2e4392907628', 'adf2a531-9330-5b8a-84c1-cae0839fedae', '6e0315ad-8603-5350-adb9-15fc133b9829', 'Supplier Credit Note Line', 'Shows one Supplier Credit Note Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 7 fields marked with a red asterisk (*) must have a value before Save will accept the record. Supplier Credit Note, Supplier Return Line and Invoice Line are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b275668c-1335-5d01-b04c-42e162dd70e9', '6e0315ad-8603-5350-adb9-15fc133b9829', 'id', 'Id', 'Immutable identity of the supplier credit line. Identifies one component of a supplier financial adjustment. Used for reconciliation, accounting, tax and audit. Stable reference for posting and reversal. Required for traceability.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('60f1d752-56ef-5462-80ad-a2b87cca3ce5', '6e0315ad-8603-5350-adb9-15fc133b9829', 'line_number', 'Line Number', 'Sequence number within the supplier credit note. Provides deterministic document ordering. Used in credit documents and reconciliation. Identifies the line during approval and posting. Required for deterministic document structure.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0614127f-b625-58be-818c-a03d1a273e19', '6e0315ad-8603-5350-adb9-15fc133b9829', 'quantity', 'Quantity', 'Quantity to which the supplier credit relates. Connects the financial adjustment to a returned or otherwise adjusted quantity. Supports quantity/value reconciliation. Must reconcile with eligible SupplierReturnLine quantity where return-originated. Supports credit calculation. Optional for purely monetary adjustments.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b1cf3f43-91bc-51e1-9383-c32af02541a0', '6e0315ad-8603-5350-adb9-15fc133b9829', 'unit_price', 'Unit Price', 'Original transaction-time unit price used to value the credited quantity. Preserves historical commercial value rather than current supplier pricing. Supports audit and reproducible credit calculation. Feeds gross credit calculation. Optional when the adjustment is not quantity-based.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8ae54055-3a35-54d0-9c38-0dec8e0183f0', '6e0315ad-8603-5350-adb9-15fc133b9829', 'gross_amount', 'Gross Amount', 'Gross credited value before discount and tax adjustments. Represents the value of the credited transaction component. Supports calculation and reconciliation. Feeds net taxable credit calculation. Required for financial calculation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ef9aa645-3f9c-5453-a49f-5e2766e1a344', '6e0315ad-8603-5350-adb9-15fc133b9829', 'discount_amount', 'Discount Amount', 'Discount component reversed or adjusted on the credited value. Preserves the original transaction discount treatment. Supports reproducibility and reconciliation. Reduces the applicable credit base. Required, including zero.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('92636c57-f137-55cb-907c-3f5d40bf1169', '6e0315ad-8603-5350-adb9-15fc133b9829', 'taxable_amount', 'Taxable Amount', 'Taxable base of the supplier credit line. Amount to which applicable tax reversal or adjustment applies. Supports tax and accounting reconciliation. Feeds tax calculation. Required for deterministic tax treatment.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('067c9d5c-4057-51fe-bc7e-d4a285bc0935', '6e0315ad-8603-5350-adb9-15fc133b9829', 'tax_amount', 'Tax Amount', 'Tax component of the supplier credit line. Reverses or adjusts tax associated with the credited amount. Supports tax reporting and accounting. Contributes to line total. Required, including zero.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
