-- Supplier Debit Note Line (bus_supplier_debit_note_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('704ce9b7-0396-5925-af00-830915fb6a18', 'bus_supplier_debit_note_line', 'Supplier Debit Note Line', 'Provides the auditable financial detail supporting one component of a SupplierDebitNote. The line explains exactly how a supplier recovery amount was calculated; it does not replace the original invoice supplier claim or claim resolution. Accounts payable supplier disputes accounting tax and audit. SupplierClaim supplies the business case, SupplierClaimResolution supplies authorization, InvoiceLine supplies original financial evidence, and SupplierDebitNote aggregates approved recovery lines. Gather source evidence → determine line basis → calculate amount and tax → validate against claim resolution → approve → post with parent SupplierDebitNote → reconcile payable. A supplier billed 100 units but 5 were not received. The SupplierClaimResolution authorizes a shortage recovery; a debit line records quantity 5 and the applicable transaction-time unit value with supporting InvoiceLine evidence.', 'factory', 'A', FALSE, FALSE, FALSE, TRUE, 'dc39239f-03b6-5135-92dc-c77a7d55fb62', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8046ba59-5ebf-5311-be0d-05d79fa44016', 'dc39239f-03b6-5135-92dc-c77a7d55fb62', '704ce9b7-0396-5925-af00-830915fb6a18', 'Supplier Debit Note Line', 'Shows one Supplier Debit Note Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Supplier Debit Note, Supplier Claim and Supplier Claim Resolution are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('42d0d728-990f-53fd-a806-0935ddd5e3e2', '704ce9b7-0396-5925-af00-830915fb6a18', 'id', 'Id', 'Immutable identity of the supplier debit line. Identifies one adjustment component independently of its parent debit note and source transactions. Accounting reconciliation audit and integration. Distinct from InvoiceLine SupplierClaim and SupplierReturnLine identities. Stable attribution for calculation and accounting. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c317e7e4-dd5d-589b-ab72-7bcd7eb6f396', '704ce9b7-0396-5925-af00-830915fb6a18', 'line_number', 'Line Number', 'Sequence number of the debit line within its SupplierDebitNote. Provides deterministic ordering and human-readable identification. Documents review and reconciliation. Unique within the parent debit note. Identifies the line during approval and posting. Required.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b296b733-d63b-587a-b4ef-d4bc6a418dfb', '704ce9b7-0396-5925-af00-830915fb6a18', 'quantity', 'Quantity', 'Quantity to which the debit calculation applies when the adjustment is quantity-based. Measures affected goods or services for shortage overcharge damage or other quantity-driven recovery. Calculation reconciliation and audit. Must reconcile with relevant InvoiceLine GoodsReceiptLine or claim evidence when applicable. Supplies quantity basis for adjustment valuation. Optional for purely monetary adjustments.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('00f07db9-3906-5587-90b2-7c97d2931ea6', '704ce9b7-0396-5925-af00-830915fb6a18', 'unit_price', 'Unit Price', 'Unit monetary value used to calculate a quantity-based debit. Captures the transaction-time valuation relevant to the recovery. Calculation and audit. Should derive from original commercial evidence rather than current master pricing. Supports reproducible line valuation. Optional for non-quantity adjustments.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9b07a6b4-c148-5ead-afdc-96fb0b193aee', '704ce9b7-0396-5925-af00-830915fb6a18', 'gross_amount', 'Gross Amount', 'Pre-tax financial amount of the debit line before applicable deductions or tax. Represents the base recovery attributable to this line. Total calculation accounting and reconciliation. Feeds taxableAmount and totalAmount. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4b79adea-bc2b-5a4e-99fc-e2687caad17b', '704ce9b7-0396-5925-af00-830915fb6a18', 'tax_amount', 'Tax Amount', 'Tax component associated with the debit line. Represents applicable tax added to the adjustment. Tax reporting and accounting. Contributes to line and header total. Required including zero.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2fb75a95-e614-53d3-9425-6f2779e32ce2', '704ce9b7-0396-5925-af00-830915fb6a18', 'net_amount', 'Net Amount', 'Final financial amount represented by this debit line. Represents the line''s gross adjustment plus applicable tax under governing calculation policy. Supplier reconciliation and accounting. Contributes to SupplierDebitNote.totalAmount. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8f0d95a2-b6bd-5d0c-b19c-3b61cea52431', '704ce9b7-0396-5925-af00-830915fb6a18', 'reason_code', 'Reason Code', 'Reason explaining why this particular debit amount is being raised. Provides line-level cause such as shortage overcharge damage or penalty. Supplier dispute reporting and recovery analytics. Complements SupplierClaim.claimType and source transaction evidence. Supports validation and approval. Required for line-level auditability.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('be3d759e-c637-5c71-846c-c3a667ac313a', '704ce9b7-0396-5925-af00-830915fb6a18', 'supplier_debit_note_id', 'Supplier Debit Note', 'Parent supplier debit note containing this line. Supplies supplier currency lifecycle and posting context. Controls whether the line can be posted.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
