INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f1e74032-6425-5190-9dc7-52d00efb30fe', '8046ba59-5ebf-5311-be0d-05d79fa44016', '42d0d728-990f-53fd-a806-0935ddd5e3e2', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Id', 'Immutable identity of the supplier debit line. Identifies one adjustment component independently of its parent debit note and source transactions. Accounting reconciliation audit and integration. Distinct from InvoiceLine SupplierClaim and SupplierReturnLine identities. Stable attribution for calculation and accounting. Required. Must be unique: a save is rejected if another Supplier Debit Note Line already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
