INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9c6ec1fc-f5e4-593b-8d64-4c4c3e315eeb', '8046ba59-5ebf-5311-be0d-05d79fa44016', 'c317e7e4-dd5d-589b-ab72-7bcd7eb6f396', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Line Number', 'Sequence number of the debit line within its SupplierDebitNote. Provides deterministic ordering and human-readable identification. Documents review and reconciliation. Unique within the parent debit note. Identifies the line during approval and posting. Required. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6050ee1f-f145-5dbd-9f3f-8a09a60e0665', '8046ba59-5ebf-5311-be0d-05d79fa44016', 'b296b733-d63b-587a-b4ef-d4bc6a418dfb', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Quantity', 'Quantity to which the debit calculation applies when the adjustment is quantity-based. Measures affected goods or services for shortage overcharge damage or other quantity-driven recovery. Calculation reconciliation and audit. Must reconcile with relevant InvoiceLine GoodsReceiptLine or claim evidence when applicable. Supplies quantity basis for adjustment valuation. Optional for purely monetary adjustments.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('68057254-357c-516a-879b-a5316803e37d', '8046ba59-5ebf-5311-be0d-05d79fa44016', '00f07db9-3906-5587-90b2-7c97d2931ea6', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Unit Price', 'Unit monetary value used to calculate a quantity-based debit. Captures the transaction-time valuation relevant to the recovery. Calculation and audit. Should derive from original commercial evidence rather than current master pricing. Supports reproducible line valuation. Optional for non-quantity adjustments.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('23aa040e-34c9-536a-a3fd-3235f7aeb507', '8046ba59-5ebf-5311-be0d-05d79fa44016', '9b07a6b4-c148-5ead-afdc-96fb0b193aee', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Gross Amount', 'Pre-tax financial amount of the debit line before applicable deductions or tax. Represents the base recovery attributable to this line. Total calculation accounting and reconciliation. Feeds taxableAmount and totalAmount. Required. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('35c70d17-6b39-54d9-8d59-12ff58d8b6f8', '8046ba59-5ebf-5311-be0d-05d79fa44016', '4b79adea-bc2b-5a4e-99fc-e2687caad17b', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Tax Amount', 'Tax component associated with the debit line. Represents applicable tax added to the adjustment. Tax reporting and accounting. Contributes to line and header total. Required including zero. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('911e18ff-0931-59cc-a90a-68e1a95d75a3', '8046ba59-5ebf-5311-be0d-05d79fa44016', '2fb75a95-e614-53d3-9425-6f2779e32ce2', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Net Amount', 'Final financial amount represented by this debit line. Represents the line''s gross adjustment plus applicable tax under governing calculation policy. Supplier reconciliation and accounting. Contributes to SupplierDebitNote.totalAmount. Required. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f19c5005-6785-5136-8d7c-de2fc3026489', '8046ba59-5ebf-5311-be0d-05d79fa44016', '8f0d95a2-b6bd-5d0c-b19c-3b61cea52431', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Reason Code', 'Reason explaining why this particular debit amount is being raised. Provides line-level cause such as shortage overcharge damage or penalty. Supplier dispute reporting and recovery analytics. Complements SupplierClaim.claimType and source transaction evidence. Supports validation and approval. Required for line-level auditability. Required — the record cannot be saved while this is empty. Up to 100 characters.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
