-- --------------------------------------------------------------------------
-- Supplier Return Line (bus_supplier_return_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'bus_supplier_return_line', 'Supplier Return Line', 'Defines exactly what previously accepted procurement quantity is being returned and connects that quantity to quality, physical and financial consequences. SupplierReturnLine is the bridge between accepted receiving evidence and quality, reverse inventory and payable workflows. Reverse logistics, supplier claims, quality, warehouse control and accounts payable. PurchaseOrderLine states the commitment; GoodsReceiptLine states accepted fulfillment; QualityInspection provides quality evidence; SupplierReturnLine states reversal; InventoryMovement records stock reduction; SupplierCreditNoteLine records payable adjustment. Validate eligible receipt quantity → inspect where required → authorize return → execute physical return → post InventoryMovement → assess supplier credit → post SupplierCreditNoteLine. Changes to receipt eligibility, inspection result, product, UOM or approved credit affecting an open line trigger revalidation of dependent return, inventory and financial workflows. Three defective units from a five-unit accepted receipt are returned. QualityInspection records the failed result and return disposition, this line records quantityReturned=3, inventory is reduced by three through an attributable movement, and any approved supplier credit is calculated from the original invoice evidence.', 'factory', 'A', FALSE, FALSE, FALSE, TRUE, '756e2833-961d-572f-8055-4e8265192c97', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('36cc0896-81f2-5010-a098-89ed26a571ec', '756e2833-961d-572f-8055-4e8265192c97', 'eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'Supplier Return Line', 'Shows one Supplier Return Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Purchase Order Line and Supplier Return are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fa656f6d-2387-57b3-8447-032092a8516b', 'eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'id', 'Id', 'Immutable identity of the supplier return line. Identifies one quantity-level reverse-procurement instruction. Used for inventory, supplier credit, quality, reconciliation and audit. Distinct from the original PurchaseOrderLine and GoodsReceiptLine identities. Provides stable attribution for every downstream reversal. Required for traceability.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2933fbdd-f7a0-5ef6-8945-10020edd4771', 'eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'line_number', 'Line Number', 'Sequence number of the return line within SupplierReturn. Provides human-readable ordering of returned items. Used in documents, warehouse operations and reconciliation. Unique within the parent return, not globally. Identifies a line during approval and execution. Required for deterministic line identification.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d381ba0a-314a-57de-ab97-48491989856e', 'eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'quantity_returned', 'Quantity Returned', 'Quantity of previously accepted goods being returned to the supplier. Measures the physical quantity leaving the organization through the reverse procurement process. Drives eligibility, inventory reversal and supplier credit calculation. Must reconcile to eligible GoodsReceiptLine accepted quantity and UOM. Primary quantity input for return execution. Required because a return line without quantity has no physical meaning.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b367dee3-ea94-548a-b57d-b08cbf316b5a', 'eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'approved_credit_amount', 'Approved Credit Amount', 'Maximum or approved financial amount eligible for supplier credit for this return line. Separates the financial claim from the physical quantity returned. Feeds SupplierCreditNote calculation and accounts-payable reconciliation. Must be derived using original transaction price, tax, discount, currency and return policy rather than current supplier pricing. Provides controlled input to financial adjustment after applicable approval. Optional where no supplier credit is expected.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('086355c6-0525-5929-954e-f048a0ac9f91', 'eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'disposition', 'Disposition', 'Operational result governing how the returned procurement quantity is handled. Identifies whether the quantity is actually being returned to the supplier or requires exception processing. Supports warehouse and supplier-claim workflows. Distinct from the original GoodsReceipt acceptance status and any QualityInspection disposition. Controls whether the normal supplier-return workflow may proceed. Required for controlled physical processing. The disposition of the supplier return line is return to supplier; set it when that is what the business means for this record. The disposition of the supplier return line is rejected; set it when that is what the business means for this record. The disposition of the supplier return line is exception; set it when that is what the business means for this record.', 1041, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e57d0e7d-29b3-5562-aeaf-8a757018b7e7', 'eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'purchase_order_line_id', 'Purchase Order Line', 'Original procurement commitment associated with the returned item. Identifies what was originally ordered. Supplies product, UOM and commercial context.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8a20d4b5-f5c1-571f-860c-34c45b5b94f9', 'eecd614d-f1f8-5e29-b5e0-5bc39e8a7468', 'supplier_return_id', 'Supplier Return', 'Parent reverse-procurement transaction containing this line. Supplies supplier, authorization and overall lifecycle context. Controls whether this line may execute.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
