INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('91adeb05-34cc-5663-a0b5-b9ec22151d19', '36cc0896-81f2-5010-a098-89ed26a571ec', '2933fbdd-f7a0-5ef6-8945-10020edd4771', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Line Number', 'Sequence number of the return line within SupplierReturn. Provides human-readable ordering of returned items. Used in documents, warehouse operations and reconciliation. Unique within the parent return, not globally. Identifies a line during approval and execution. Required for deterministic line identification. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3c72256b-e636-51f5-a634-277bc7ecd97c', '36cc0896-81f2-5010-a098-89ed26a571ec', 'd381ba0a-314a-57de-ab97-48491989856e', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Quantity Returned', 'Quantity of previously accepted goods being returned to the supplier. Measures the physical quantity leaving the organization through the reverse procurement process. Drives eligibility, inventory reversal and supplier credit calculation. Must reconcile to eligible GoodsReceiptLine accepted quantity and UOM. Primary quantity input for return execution. Required because a return line without quantity has no physical meaning. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('280a7e87-b54a-585d-b6ca-732f1f42b1af', '36cc0896-81f2-5010-a098-89ed26a571ec', 'b367dee3-ea94-548a-b57d-b08cbf316b5a', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Approved Credit Amount', 'Maximum or approved financial amount eligible for supplier credit for this return line. Separates the financial claim from the physical quantity returned. Feeds SupplierCreditNote calculation and accounts-payable reconciliation. Must be derived using original transaction price, tax, discount, currency and return policy rather than current supplier pricing. Provides controlled input to financial adjustment after applicable approval. Optional where no supplier credit is expected.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bb7b92f7-27e9-5e60-89b6-5129cb5b0aea', '36cc0896-81f2-5010-a098-89ed26a571ec', '086355c6-0525-5929-954e-f048a0ac9f91', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Disposition', 'Operational result governing how the returned procurement quantity is handled. Identifies whether the quantity is actually being returned to the supplier or requires exception processing. Supports warehouse and supplier-claim workflows. Distinct from the original GoodsReceipt acceptance status and any QualityInspection disposition. Controls whether the normal supplier-return workflow may proceed. Required for controlled physical processing. The disposition of the supplier return line is return to supplier; set it when that is what the business means for this record. The disposition of the supplier return line is rejected; set it when that is what the business means for this record. The disposition of the supplier return line is exception; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6df4008a-2904-5a13-9f26-c8f62ff113b8', '36cc0896-81f2-5010-a098-89ed26a571ec', 'e57d0e7d-29b3-5562-aeaf-8a757018b7e7', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Purchase Order Line', 'Original procurement commitment associated with the returned item. Identifies what was originally ordered. Supplies product, UOM and commercial context. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2a5cd4b6-3ca5-5d69-8493-66735d8d7945', '36cc0896-81f2-5010-a098-89ed26a571ec', '8a20d4b5-f5c1-571f-860c-34c45b5b94f9', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Supplier Return', 'Parent reverse-procurement transaction containing this line. Supplies supplier, authorization and overall lifecycle context. Controls whether this line may execute. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
