INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bf2ad378-619b-548f-97fd-e2c3b77183e8', 'd25babe6-1284-5194-aedd-935b223d4afc', 'cb072910-cabb-5c82-a344-7322603fb67f', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Id', 'Immutable identity of the original invoice line. Identifies the historical billed detail independently of later credits or corrections. Used for billing, audit, matching, credit and reconciliation. CreditNoteLine and SupplierCreditNoteLine may reference this identity as source evidence. Stable root reference for the line lifecycle. Required for financial traceability. Must be unique: a save is rejected if another Invoice Line already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('15f45ac2-7c7b-5396-a249-c81e72c500ee', 'd25babe6-1284-5194-aedd-935b223d4afc', '9e3e4ae5-b9e5-53a8-9860-163bbbc0a980', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Line Number', 'Sequence number within the invoice. Identifies the line for documents and reconciliation. Used in invoice presentation and audit. Unique within Invoice and distinct from CreditNoteLine and SupplierCreditNoteLine numbering. Supports deterministic document reconstruction. Required. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('82dd1ef8-5ee5-5c50-b14c-976f6d615198', 'd25babe6-1284-5194-aedd-935b223d4afc', '353b6b42-1d90-50c2-a893-e1059767d681', '0323a290-d08f-5b0e-a57b-b396a1b4b4eb', 'Quantity', 'Originally billed quantity. Preserves the historical quantity on the original claim. Used for billing, matching and return eligibility. CustomerReturnLine or SupplierReturnLine may reference eligible quantities and CreditNoteLine or SupplierCreditNoteLine may credit an eligible portion. Provides source quantity evidence. Optional for purely monetary lines.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9389e7e5-2625-5ef9-b06a-94f16f3f6c18', 'd25babe6-1284-5194-aedd-935b223d4afc', 'd8d4a854-ea83-5613-9593-be7c992b0d17', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Unit Price', 'Transaction-time billed price per unit. Captures the price actually used to value the invoice line, not today''s master price. Supports invoice calculation, audit, price variance, settlement and credit calculation. Customer or supplier credit lines may preserve this as source valuation evidence; later pricing changes do not rewrite it. Provides authoritative historical pricing evidence for the invoice line. Optional for non-quantity monetary lines.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fdec2838-a294-59e3-a7e6-364c4c0399d7', 'd25babe6-1284-5194-aedd-935b223d4afc', '16adfc10-0499-5289-8088-e3d3cc8b2647', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Gross Amount', 'Gross monetary value before line discount and tax. Original calculated value of the billed line. Used for invoice reconciliation and credit evidence. Credit adjustment lines do not mutate this historical amount. Feeds original line calculation. Required. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1ced581f-94b1-5aaf-887b-63aa4c385811', 'd25babe6-1284-5194-aedd-935b223d4afc', '9fe3e108-6be0-556d-8358-1b35c2d2bd7a', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Discount Amount', 'Discount originally applied to the line. Historical line-level commercial reduction. Used for reproducibility, tax and credit calculation. Return credits use original discount evidence where policy requires. Contributes to original taxable and net values. Required, including zero. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c15bb400-4964-5dcd-b1f2-662d1f243355', 'd25babe6-1284-5194-aedd-935b223d4afc', '4de3c28d-8303-5f1a-9472-8593bcda52a1', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Taxable Amount', 'Original taxable base of the invoice line. Amount subjected to the original tax treatment. Used for tax audit and credit calculation. Credit adjustment tax evidence may derive from this historical treatment. Provides source tax basis. Required. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a7dd5c04-543a-53c3-bdb3-ce7076a7f876', 'd25babe6-1284-5194-aedd-935b223d4afc', '2832d4a9-abc5-5693-b55b-b0a1076d7fd4', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Tax Amount', 'Tax originally recognized on the line. Historical tax component of the claim. Used for tax reporting, accounting and credit calculation. A credit line may reverse an eligible portion without editing this amount. Provides source tax evidence. Required, including zero. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('35bcdaa8-edb4-5d85-97bf-a1b7efb65406', 'd25babe6-1284-5194-aedd-935b223d4afc', 'bc417cf4-a78d-5423-b839-f8bc1b72f26b', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Net Amount', 'Original net financial value of the line after discount and applicable tax treatment. Historical line contribution to the Invoice total. Used for billing, accounting and credit reference. Credit adjustment lines record a separate reduction rather than changing netAmount. Provides immutable source value. Required. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('081b089e-a1ad-539f-b0b6-550ebaabac5e', 'd25babe6-1284-5194-aedd-935b223d4afc', '1bb4faa4-8ee3-5fcd-a5ac-41a965fb2839', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Pricing Evidence', 'Snapshot of material pricing inputs used to determine the invoice line amount. Preserves source, effective date, and approved commercial context needed to reproduce pricing even when master data changes. Supports audit, dispute resolution, recalculation, credit calculation and integration. Links the invoice result to the effective transaction price without making the posted invoice depend on mutable pricing master data.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('37989c9c-768d-5372-96fd-e4b51a357a45', 'd25babe6-1284-5194-aedd-935b223d4afc', 'ac0207f2-da37-5313-ba2d-71775621bf77', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Discount Evidence', 'Snapshot of the discount policy inputs and result used on the invoice line. Preserves the applied discount rule/version, method, base, rate or fixed amount, and resulting discount. Supports audit and prevents later DiscountRule changes from altering historical calculations or credits. Provides reproducible discount calculation evidence.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a9f18757-a12d-50cb-a249-f2d905948b41', 'd25babe6-1284-5194-aedd-935b223d4afc', '06cad0da-aa94-5d55-acf2-79f4cb80dd0a', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Tax Evidence', 'Snapshot of the tax determination inputs and result used on the invoice line. Preserves tax rule/version, jurisdiction, rate, taxable base, rounding and calculated tax. Supports tax audit, compliance, dispute resolution and credit-note tax calculation. Prevents later TaxRule changes from rewriting posted invoice tax.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('38a2517e-fa5c-5850-8e76-4660843abcd6', 'd25babe6-1284-5194-aedd-935b223d4afc', '80b9a9a3-86a3-581c-aab7-e8447ee1e17a', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Description', 'Human-readable description of the original billed line. Describes the billed good or service. Used on documents and audit. Complements Product and source transaction references. Supports document presentation. Optional descriptive context. Up to 1000 characters.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1c6056c0-dd78-5898-b2cc-c23325c3e4ec', 'd25babe6-1284-5194-aedd-935b223d4afc', 'd1c58cd3-15bc-5176-8642-4dd0c70e98ea', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Matching Status', 'Procurement matching state of the invoice line. Indicates whether the line agrees with applicable purchase and receipt evidence. Used for accounts payable controls and reconciliation. Independent from CreditNote and SupplierCreditNote status; a credit may correct a posted line after matching. Controls matching approval before posting. The matching status of the invoice line is not applicable; set it when that is what the business means for this record. The matching status of the invoice line is unmatched; set it when that is what the business means for this record. The matching status of the invoice line is matched; set it when that is what the business means for this record. The matching status of the invoice line is partially matched; set it when that is what the business means for this record. The matching status of the invoice line is exception; set it when that is what the business means for this record. The matching status of the invoice line is waived; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
